1	/*
2	 * Copyright (c) 2023-2024 C*Core Technology Co.,Ltd,Suzhou.
3	 * Ventus-RTL is licensed under Mulan PSL v2.
4	 * You can use this software according to the terms and conditions of the Mulan PSL v2.
5	 * You may obtain a copy of Mulan PSL v2 at:
6	 *          http://license.coscl.org.cn/MulanPSL2
7	 * THIS SOFTWARE IS PROVIDED ON AN "AS IS" BASIS, WITHOUT WARRANTIES OF ANY KIND,
8	 * EITHER EXPRESS OR IMPLIED, INCLUDING BUT NOT LIMITED TO NON-INFRINGEMENT,
9	 * MERCHANTABILITY OR FIT FOR A PARTICULAR PURPOSE.
10	 * See the Mulan PSL v2 for more details. */
11	// Author: Zhang, Qi
12	// Description:
13	`timescale 1ns/1ns
14	
15	`include "define.v"
16	
17	module simt_stack (
18	  input                    clk                    ,
19	  input                    rst_n                  ,
20	
21	  output                   branch_ctl_ready_o     ,
22	  input                    branch_ctl_valid_i     ,
23	  input                    branch_ctl_opcode_i    , //1 -> join / 0 -> branch
24	  input  [`DEPTH_WARP-1:0] branch_ctl_wid_i       , 
25	  input  [31:0]            branch_ctl_pc_branch_i , 
26	  input  [31:0]            branch_ctl_pc_execute_i, //executing pc
27	  input  [`NUM_THREAD-1:0] branch_ctl_mask_init_i ,
28	
29	  output                   if_mask_ready_o        ,
30	  input                    if_mask_valid_i        ,
31	  input  [`NUM_THREAD-1:0] if_mask_mask_i         , //if mask
32	  input  [`DEPTH_WARP-1:0] if_mask_wid_i          ,
33	
34	  input                    pc_reconv_valid_i      ,
35	  input  [`XLEN-1:0]       pc_reconv_i            , //reconv pc
36	
37	  input  [`DEPTH_WARP-1:0] input_wid_i            ,
38	  output [`NUM_THREAD-1:0] out_mask_o             ,
39	
40	  output                   complete_valid_o       ,
41	  output [`DEPTH_WARP-1:0] complete_wid_o         ,
42	
43	  input                    fetch_ctl_ready_i      ,
44	  output                   fetch_ctl_valid_o      ,
45	  output [`DEPTH_WARP-1:0] fetch_ctl_wid_o        ,
46	  output                   fetch_ctl_jump_o       ,
47	  output [31:0]            fetch_ctl_new_pc_o        
48	  );
49	
50	  wire branch_ctl_buf_fire;
51	  reg  branch_ctl_buf_ready_i;
52	  wire branch_ctl_buf_valid_o;
53	  wire branch_ctl_buf_opcode_o;    
54	  wire [`DEPTH_WARP-1:0] branch_ctl_buf_wid_o;      
55	  wire [31:0] branch_ctl_buf_pc_branch_o; 
56	  wire [31:0] branch_ctl_buf_pc_execute_o;
57	  wire [`NUM_THREAD-1:0] branch_ctl_buf_mask_init_o;  
58	  wire [(1+`DEPTH_WARP+32+32+`NUM_THREAD)-1:0] branch_ctl_buf_i;
59	  wire [(1+`DEPTH_WARP+32+32+`NUM_THREAD)-1:0] branch_ctl_buf_o; 
60	
61	  //wire if_mask_buf_fire;
62	  //wire if_mask_buf_ready_i;
63	  //wire if_mask_buf_valid_o;
64	  //wire [`NUM_THREAD-1:0] if_mask_buf_mask_o;
65	  //wire [`DEPTH_WARP-1:0] if_mask_buf_wid_o;
66	  //wire [`NUM_THREAD+`DEPTH_WARP-1:0] if_mask_buf_i;
67	  //wire [`NUM_THREAD+`DEPTH_WARP-1:0] if_mask_buf_o;
68	
69	  wire pc_reconv_ready_o;
70	  wire pc_reconv_buf_valid_o;
71	  reg  pc_reconv_buf_ready_i;
72	  wire [`XLEN-1:0] pc_reconv_buf_o;
73	
74	  wire fetch_ctl_buf_ready_o;
75	  reg  fetch_ctl_buf_valid_i;
76	  reg  fetch_ctl_buf_jump_i;
77	  reg  [31:0] fetch_ctl_buf_new_pc_i;
78	  wire [`DEPTH_WARP+32+1-1:0] fetch_ctl_buf_i;
79	  wire [`DEPTH_WARP+32+1-1:0] fetch_ctl_buf_o;
80	
81	  //reg [`NUM_THREAD-1:0] thread_masks [0:`NUM_WARP-1];
82	  reg [`NUM_WARP*`NUM_THREAD-1:0] thread_masks;
83	
84	  wire [`NUM_THREAD-1:0] if_mask,else_mask;
85	  wire if_only,else_only,div_occur;
86	                                   
87	  wire [`DEPTH_THREAD:0] if_cnt,else_cnt; // the number of 1 in the if_mask or else_mask
88	  wire take_if; 
89	
90	  //wire push [0:`NUM_WARP-1];
91	  //wire pop [0:`NUM_WARP-1];
92	  //wire bj_jump [0:`NUM_WARP-1];
93	  wire [`NUM_WARP-1:0] push;
94	  wire [`NUM_WARP-1:0] pop;
95	  wire [`NUM_WARP-1:0] bj_jump;
96	  wire [31:0] bj_pc [0:`NUM_WARP-1];
97	  wire [`NUM_THREAD-1:0] bj_mask [0:`NUM_WARP-1];
98	  wire bj_empty [0:`NUM_WARP-1];
99	
100	  reg [31:0]            pushdata_jump_pc ;
101	  reg [`NUM_THREAD-1:0] pushdata_new_mask;
102	
103	  assign branch_ctl_buf_i = {branch_ctl_mask_init_i,branch_ctl_pc_execute_i,
104	                             branch_ctl_pc_branch_i,branch_ctl_wid_i,
105	                             branch_ctl_opcode_i};
106	
107	  assign {branch_ctl_buf_mask_init_o,branch_ctl_buf_pc_execute_o,
108	          branch_ctl_buf_pc_branch_o,branch_ctl_buf_wid_o,
109	          branch_ctl_buf_opcode_o} = branch_ctl_buf_o;
110	
111	  assign branch_ctl_buf_fire = branch_ctl_buf_ready_i && branch_ctl_buf_valid_o;
112	
113	  //assign if_mask_buf_i = {if_mask_wid_i,if_mask_mask_i};
114	  //assign {if_mask_buf_wid_o,if_mask_buf_mask_o} = if_mask_buf_o;
115	  //assign {if_mask_buf_wid_o,if_mask_buf_mask_o} = if_mask_buf_i;
116	  //assign if_mask_buf_wid_o = if_mask_wid_i;
117	  //assign if_mask_buf_mask_o = if_mask_mask_i;
118	  //assign if_mask_buf_ready_i = fetch_ctl_buf_ready_o;
119	  assign if_mask_ready_o = fetch_ctl_buf_ready_o;
120	  //assign if_mask_buf_fire = if_mask_buf_ready_i && if_mask_buf_valid_o;
121	  assign if_mask_buf_fire = if_mask_ready_o && if_mask_valid_i;
122	
123	  //******  output fetch control  ********
124	  //issue fetch request when: 
125	  //1. branch happen and take else path  
126	  //2. join happen and jump indeed happen
127	  assign fetch_ctl_buf_i = {fetch_ctl_buf_new_pc_i,fetch_ctl_buf_jump_i,branch_ctl_buf_wid_o};
128	  assign {fetch_ctl_new_pc_o,fetch_ctl_jump_o,fetch_ctl_wid_o} = fetch_ctl_buf_o;
129	
130	  always @(*) begin
131	    if(branch_ctl_buf_opcode_o && branch_ctl_buf_valid_o) begin
132	      fetch_ctl_buf_new_pc_i = (bj_jump[branch_ctl_buf_wid_o]) ? bj_pc[branch_ctl_buf_wid_o] : 'h0;
133	      fetch_ctl_buf_jump_i = (bj_jump[branch_ctl_buf_wid_o]) ? 'h1 : 'h0;
134	      fetch_ctl_buf_valid_i = 'h1;
135	    end
136	    else if((!branch_ctl_buf_opcode_o) && branch_ctl_buf_valid_o && if_mask_valid_i && ((!take_if) || else_only)) begin
137	      fetch_ctl_buf_new_pc_i = branch_ctl_buf_pc_branch_o;
138	      fetch_ctl_buf_jump_i = 'h1;
139	      fetch_ctl_buf_valid_i = 'h1;
140	    end
141	    else begin
142	      fetch_ctl_buf_new_pc_i = 'h0;
143	      fetch_ctl_buf_jump_i = 'h0;
144	      fetch_ctl_buf_valid_i = 'h0;
145	    end 
146	  end 
147	
148	  assign complete_valid_o = (if_mask_buf_fire && (!branch_ctl_buf_opcode_o) && branch_ctl_buf_valid_o && take_if);
149	  assign complete_wid_o = branch_ctl_buf_wid_o; 
150	
151	  always @(*) begin
152	    if(fetch_ctl_buf_ready_o) begin
153	      if(branch_ctl_buf_valid_o && (!branch_ctl_buf_opcode_o) && (branch_ctl_buf_wid_o == if_mask_wid_i)) begin
154	        branch_ctl_buf_ready_i = if_mask_buf_fire;
155	        pc_reconv_buf_ready_i = if_mask_buf_fire;
156	      end 
157	      else if(branch_ctl_buf_valid_o && branch_ctl_buf_opcode_o) begin
158	        branch_ctl_buf_ready_i = 1'h1;
159	        pc_reconv_buf_ready_i = 1'h1;
160	      end
161	      else begin
162	        branch_ctl_buf_ready_i = 1'h0;
163	        pc_reconv_buf_ready_i = 1'h0;
164	      end
165	    end 
166	    else begin
167	      branch_ctl_buf_ready_i = 1'h0;
168	      pc_reconv_buf_ready_i = 1'h0;
169	    end 
170	  end 
171	
172	  assign if_mask = if_mask_mask_i & branch_ctl_buf_mask_init_o;
173	  assign else_mask = (~if_mask) & branch_ctl_buf_mask_init_o;
174	
175	  assign take_if = ((if_cnt < else_cnt) && div_occur) || if_only; // take if first if thread take if path is less than thread take else
176	  assign if_only = (else_mask == 'h0);
177	  assign else_only = (if_mask == 'h0);
178	  assign div_occur = !(if_only || else_only);// div_occur indicate that true divergence occurs, 
179	                                             // that is, nether if_mask nor else_mask is all zero
180	  always @(*) begin
181	    if(take_if) begin
182	      pushdata_new_mask = else_mask;
183	      pushdata_jump_pc = branch_ctl_buf_pc_branch_o;
184	    end
185	    else begin
186	      pushdata_new_mask = if_mask;
187	      pushdata_jump_pc = branch_ctl_buf_pc_execute_o + 3'h4;
188	    end 
189	  end 
190	
191	  genvar i;
192	  generate for(i=0;i<`NUM_WARP;i=i+1) begin:B1
193	    assign push[i] = (!branch_ctl_buf_opcode_o) && branch_ctl_buf_fire && (i == branch_ctl_buf_wid_o) && div_occur; 
194	    assign pop[i] = (branch_ctl_buf_opcode_o) && branch_ctl_buf_fire && (i == branch_ctl_buf_wid_o); //just indicating this is join, maybe not pop, 
195	
196	    branch_join_stack #(
197	      .ADDR_WIDTH($clog2(`DEPTH_THREAD)+20)
198	      ) bjstack(
199	      .clk                (clk                                              ),
200	      .rst_n              (rst_n                                            ),
201	      .push_i             (push[i]                                          ),
202	      .pop_i              (pop[i]                                           ),
203	      .pushdata_recon_pc_i(pc_reconv_buf_o                                  ),
204	      .pushdata_jump_pc_i (pushdata_jump_pc                                 ),
205	      .pushdata_new_mask_i(pushdata_new_mask                                ),
206	      .thread_mask_i      (thread_masks[(`NUM_THREAD*(i+1)-1)-:`NUM_THREAD] ),
207	      .pc_execute_i       (branch_ctl_buf_pc_execute_o                      ),
208	      .jump_o             (bj_jump[i]                                       ),
209	      .new_pc_o           (bj_pc[i]                                         ),
210	      .new_mask_o         (bj_mask[i]                                       ),
211	      .stack_empty_o      (bj_empty[i]                                      )
212	      ); 
213	  end 
214	  endgenerate
215	
216	  //************************thread mask register control************************
217	  //when branch indeed happened, put executing mask into corresponding register
218	  //when join indeed happened, put new mask into corresponding register
219	  //genvar j;
220	  //generate for(j=0;j<`NUM_WARP;j=j+1) begin:B2
221	  //  always @(posedge clk or negedge rst_n) begin
222	  //    if(!rst_n) begin
223	  //      thread_masks[j] <= {`NUM_THREAD{1'h1}};
224	  //    end 
225	  //    else if(if_mask_buf_fire && div_occur) begin
226	  //      thread_masks[branch_ctl_buf_wid_o] <= (take_if) ? if_mask : else_mask;
227	  //    end
228	  //    else if(branch_ctl_buf_opcode_o && branch_ctl_buf_valid_o && bj_jump[branch_ctl_buf_wid_o]) begin
229	  //      thread_masks[branch_ctl_buf_wid_o] <= bj_mask[branch_ctl_buf_wid_o];
230	  //    end
231	  //    else begin
232	  //      thread_masks[j] <= thread_masks[j];
233	  //    end 
234	  //  end 
235	  //end 
236	  //endgenerate
237	  always @(posedge clk or negedge rst_n) begin
238	    if(!rst_n) begin
239	      thread_masks <= {`NUM_WARP*`NUM_THREAD{1'h1}};
240	    end 
241	    else if(if_mask_buf_fire && div_occur) begin
242	      thread_masks[(`NUM_THREAD*(branch_ctl_buf_wid_o+1)-1)-:`NUM_THREAD] <= (take_if) ? if_mask : else_mask; 
243	    end 
244	    else if(branch_ctl_buf_opcode_o && branch_ctl_buf_valid_o && bj_jump[branch_ctl_buf_wid_o]) begin
245	      thread_masks[(`NUM_THREAD*(branch_ctl_buf_wid_o+1)-1)-:`NUM_THREAD] <= bj_mask[branch_ctl_buf_wid_o];
246	    end
247	    else if(bj_empty[branch_ctl_buf_wid_o]) begin
248	      thread_masks[(`NUM_THREAD*(branch_ctl_buf_wid_o+1)-1)-:`NUM_THREAD] <= {`NUM_THREAD{1'h1}};
249	    end 
250	    else begin
251	      thread_masks <= thread_masks;
252	    end 
253	  end 
254	
255	  assign out_mask_o = thread_masks[(`NUM_THREAD*(input_wid_i+1)-1)-:`NUM_THREAD];
256	
257	  //stream_fifo_flow_true #(
258	  stream_fifo #(
259	    .DATA_WIDTH(1+`DEPTH_WARP+32+32+`NUM_THREAD),
260	    .FIFO_DEPTH(1                              )
261	    ) branch_ctl_buf(
262	    .clk      (clk                   ),
263	    .rst_n    (rst_n                 ),
264	             
265	    .w_ready_o(branch_ctl_ready_o    ),
266	    .w_valid_i(branch_ctl_valid_i    ),
267	    .w_data_i (branch_ctl_buf_i      ),
268	             
269	    .r_valid_o(branch_ctl_buf_valid_o),
270	    .r_ready_i(branch_ctl_buf_ready_i),
271	    .r_data_o (branch_ctl_buf_o      )
272	    );   
273	
274	  //stream_fifo_entry_zero #(
275	  //  .DATA_WIDTH(`NUM_THREAD+`DEPTH_WARP)
276	  //  ) if_mask_buf(
277	  //  .w_ready_o(if_mask_ready_o    ),
278	  //  .w_valid_i(if_mask_valid_i    ),
279	  //  .w_data_i (if_mask_buf_i      ),
280	  //           
281	  //  .r_valid_o(if_mask_buf_valid_o),
282	  //  .r_ready_i(if_mask_buf_ready_i),
283	  //  .r_data_o (if_mask_buf_o      )
284	  //  );
285	
286	  //stream_fifo_flow_true #(
287	  stream_fifo #(
288	    .DATA_WIDTH(`XLEN),
289	    .FIFO_DEPTH(1    )
290	    ) pc_reconv_buf(
291	    .clk      (clk                  ),
292	    .rst_n    (rst_n                ),
293	             
294	    .w_ready_o(pc_reconv_ready_o    ),
295	    .w_valid_i(pc_reconv_valid_i    ),
296	    .w_data_i (pc_reconv_i          ),
297	             
298	    .r_valid_o(pc_reconv_buf_valid_o),
299	    .r_ready_i(pc_reconv_buf_ready_i),
300	    .r_data_o (pc_reconv_buf_o      )
301	    );   
302	
303	  //stream_fifo_flow_true #(
304	  stream_fifo #(
305	    .DATA_WIDTH(`DEPTH_WARP+32+1),
306	    .FIFO_DEPTH(1               )
307	    ) fetch_ctl_buf(
308	    .clk      (clk                  ),
309	    .rst_n    (rst_n                ),
310	             
311	    .w_ready_o(fetch_ctl_buf_ready_o),
312	    .w_valid_i(fetch_ctl_buf_valid_i),
313	    .w_data_i (fetch_ctl_buf_i      ),
314	             
315	    .r_valid_o(fetch_ctl_valid_o    ),
316	    .r_ready_i(fetch_ctl_ready_i    ),
317	    .r_data_o (fetch_ctl_buf_o      )
318	    );   
319	
320	  pop_cnt #(
321	    .DATA_LEN(`NUM_THREAD    ),  
322	    .DATA_WID(`DEPTH_THREAD+1)
323	    ) cnt_if_mask(
324	    .data_i(if_mask),
325	    .data_o(if_cnt )
326	    );
327	
328	  pop_cnt #(
329	    .DATA_LEN(`NUM_THREAD    ),
330	    .DATA_WID(`DEPTH_THREAD+1)
331	    ) cnt_else_mask(
332	    .data_i(else_mask),
333	    .data_o(else_cnt )
334	    );
335	
336	endmodule
337

